pm.test("Media asset registered (201)", () => pm.response.to.have.status(201));
const body = pm.response.json();
pm.expect(body.titleId).to.be.a("string").and.not.empty;
pm.expect(body.mediaUrl).to.be.a("string").and.not.empty;
