// Wire titleId from Catalog -> streamingTitleId so Streaming tests run without manual seeding.
pm.environment.set("streamingTitleId", body.titleId);

pm.test("Upsert returns 201 for existing asset", () => pm.response.to.have.status(201));
const body = pm.response.json();
pm.expect(body.titleId).to.eql(pm.environment.get("streamingTitleId"));
pm.expect(body.durationSeconds).to.eql(5401);
